insert into natural_english_private.catalogue(module,senses,questions) values
('advanced-native-1665', '["phrase"]'::jsonb, '{"advanced-native-1665-v1-audio":{"type":"mc","answers":["小組調整一項安排，並非刪掉所有享受。"],"options":["每周遊戲夜與編輯同時進行，是句子描述的解決方法。","小組調整一項安排，並非刪掉所有享受。","小組已取消每周遊戲夜，改成每晚編輯。","小組完全沒有改時間，仍按原有編輯安排。"]},"advanced-native-1665-v2-reply":{"type":"mc","answers":["No, we did not need to cut out everything we enjoy; we changed one editing time.","We kept the weekly games night and edited at a different time.","The plan needed an adjustment rather than a complete loss of leisure.","We made room for the project without cancelling every activity we liked."],"options":["No, we did not need to cut out everything we enjoy; we changed one editing time.","We kept the weekly games night and edited at a different time.","The plan needed an adjustment rather than a complete loss of leisure.","We made room for the project without cancelling every activity we liked."]},"advanced-native-1665-v1-scene":{"type":"mc","answers":["She need not cut out everything she enjoys to make room for practice."],"options":["She need not cut out everything she enjoys to make room for practice.","She has abandoned every hobby, including the Saturday choir.","She treats the choir as the language practice itself, rather than keeping both activities."]},"advanced-native-1665-v1-contrast":{"type":"mc","answers":["已經刪去全部享受，只是事後認為不值得。"],"options":["已經刪去全部享受，只是事後認為不值得。","可考慮局部調整，保留某些喜歡的活動。","不一定要全面取消喜歡的事物。"]},"advanced-native-1665-v1-branch":{"type":"mc","answers":["We need not cut out everything we enjoy, but we did make a specific change to fit the work in."],"options":["Move the editing back to the same evening and assume the two activities will fit without discussion.","We need not cut out everything we enjoy, but we did make a specific change to fit the work in.","Keeping the games night means the original editing time never changed."]},"advanced-native-1665-v1-final":{"type":"open","answers":["We need not cut out everything we enjoy; we can keep the park drawing and home reading sessions while dropping one costly venue booking.","Cancelling that booking does not mean we must cut out everything we enjoy. Let us keep the activities that work without the extra venue cost."],"options":[]}}'::jsonb),
('advanced-native-1667', '["phrase"]'::jsonb, '{"advanced-native-1667-v1-audio":{"type":"mc","answers":["小組條件讓她更能主動發問及回應。"],"options":["她只是坐在小組內，敘述沒有任何參與表現。","她在大型講座已一直主導討論，小組反而只旁聽。","例子主要顯示上課時間縮短，而非她參與方式改變。","小組條件讓她更能主動發問及回應。"]},"advanced-native-1667-v2-reply":{"type":"mc","answers":["She can take an active part in a way she did not in the large lecture.","The discussion conditions bring out her curiosity and responses.","She thrives in that setting because she has time to form questions and respond.","The pace gives her room to contribute rather than remain silent."],"options":["She can take an active part in a way she did not in the large lecture.","The discussion conditions bring out her curiosity and responses.","She thrives in that setting because she has time to form questions and respond.","The pace gives her room to contribute rather than remain silent."]},"advanced-native-1667-v1-scene":{"type":"mc","answers":["She thrives in a setting that combines clear deadlines with freedom over the method."],"options":["She thrives in a setting that combines clear deadlines with freedom over the method.","She is present in the studio but has not produced or revised any work.","The example shows that deadlines prevent her from contributing."]},"advanced-native-1667-v1-contrast":{"type":"mc","answers":["只知道人物出現在該處，沒任何發展或表現資料。"],"options":["特定條件讓人物比原來更能發揮長處。","持續主動參與，作品及理解有進展。","只知道人物出現在該處，沒任何發展或表現資料。"]},"advanced-native-1667-v1-branch":{"type":"mc","answers":["She thrives in that setting, but we should ask what helps the other students rather than assume the same fit."],"options":["She thrives in that setting, but we should ask what helps the other students rather than assume the same fit.","Use her experience as the complete evidence for every student’s preference.","Change next week’s whole-class format before asking the others which conditions help them."]},"advanced-native-1667-v1-final":{"type":"open","answers":["She thrives in roles with clear responsibilities and direct contact with people, as I saw when she helped visitors at our community stall. She would still need training in the library system.","I think she would thrive in your welcome team because she listens carefully and enjoys finding the right information for visitors. A guided introduction to the system would help her begin."],"options":[]}}'::jsonb),
('advanced-native-1668', '["phrase"]'::jsonb, '{"advanced-native-1668-v1-audio":{"type":"mc","answers":["一項小安排帶來人物認為有用的漸進改善。"],"options":["材料被放回原處，早晨節奏沒有改變。","主要變化是旅程路線已縮短，而非早晨安排。","一項小安排帶來人物認為有用的漸進改善。","人物已不需再出門，所有行程都取消。"]},"advanced-native-1668-v2-reply":{"type":"mc","answers":["I could begin the day with less searching and hurry.","The small routine improved one part of the day without changing the whole journey.","I felt a modest but useful shift in how the morning worked.","It began to gently pull life in a better direction by making my mornings less rushed."],"options":["I could begin the day with less searching and hurry.","The small routine improved one part of the day without changing the whole journey.","I felt a modest but useful shift in how the morning worked.","It began to gently pull life in a better direction by making my mornings less rushed."]},"advanced-native-1668-v1-scene":{"type":"mc","answers":["The small habit can gently pull life in a better direction for her."],"options":["Although she keeps the list, her birthday responses have not changed.","The small habit can gently pull life in a better direction for her.","The birthday messages show that she has replaced her entire weekly routine at once."]},"advanced-native-1668-v1-contrast":{"type":"mc","answers":["這項小改變本身已等於一次全面重排整個生活。"],"options":["這項小改變本身已等於一次全面重排整個生活。","要有具體生活線索，才知道 better 對人物指甚麼。","小改變可逐漸帶來人物重視的改善。"]},"advanced-native-1668-v1-branch":{"type":"mc","answers":["The change helped the morning routine, not the length of the journey; better direction has a specific scope here."],"options":["We should describe the preparation as useless because the journey remains demanding.","The change helped the morning routine, not the length of the journey; better direction has a specific scope here.","The calmer morning is enough to establish that the journey takes fewer minutes."]},"advanced-native-1668-v1-final":{"type":"open","answers":["Perhaps a short voice message each week could gently pull life in a better direction for us, keeping ordinary moments in our conversation. We need not wait for a long formal call.","I would like us to try one small weekly exchange that might gently pull life in a better direction. Hearing a little about your day would help me feel more connected."],"options":[]}}'::jsonb),
('advanced-native-1669', '["phrase"]'::jsonb, '{"advanced-native-1669-v1-audio":{"type":"mc","answers":["小組想一次全面改安排，但仍需具體了解各組時間。"],"options":["首次討論是先前多次小改動的最後一次記錄，沒有全面重排想法。","小組想一次全面改安排，但仍需具體了解各組時間。","The committee planned a trial change to one clashing slot before considering any wider redesign.","每組已確認新時段，討論只在宣布結果。"]},"advanced-native-1669-v2-reply":{"type":"mc","answers":["They hoped one dramatic reset would deal with the repeated clashes.","They wanted a comprehensive restart rather than another small adjustment.","The plan was to reorganise the whole timetable in one major move.","They were seeking a broad change, although individual availability still needed checking."],"options":["They hoped one dramatic reset would deal with the repeated clashes.","They wanted a comprehensive restart rather than another small adjustment.","The plan was to reorganise the whole timetable in one major move.","They were seeking a broad change, although individual availability still needed checking."]},"advanced-native-1669-v1-scene":{"type":"mc","answers":["She is planning one dramatic reset rather than a minor revision."],"options":["The new plan has already proved easier to sustain over several months.","She has kept the topic, times and collaborators unchanged and altered only the title.","She is planning one dramatic reset rather than a minor revision."]},"advanced-native-1669-v1-contrast":{"type":"mc","answers":["大改動的成果已確立，往後不用再檢視。"],"options":["可與許多小步調整的方式作比較。","一次顯著而幅度大的重新安排。","大改動的成果已確立，往後不用再檢視。"]},"advanced-native-1669-v1-branch":{"type":"mc","answers":["One dramatic reset does not supply that information; we still need each group’s availability."],"options":["Use the scale of the redesign as evidence that every new slot suits its group.","Ask about availability only after publishing the complete new timetable.","One dramatic reset does not supply that information; we still need each group’s availability."]},"advanced-native-1669-v1-final":{"type":"open","answers":["Before choosing one dramatic reset of the whole book, I would like to ask where readers lose the thread. A focused revision of this chapter may tell us more.","One dramatic reset is an option, but I have not yet found out what makes the chapter hard to follow. Let us get that feedback before deciding how much to rewrite."],"options":[]}}'::jsonb),
('advanced-native-1670', '["phrase"]'::jsonb, '{"advanced-native-1670-v1-audio":{"type":"mc","answers":["兩人見面很罕有，這次因而難得。"],"options":["句子指定兩人每隔某個確切月數就會見面。","兩人見面很罕有，這次因而難得。","兩人每周按固定時間見面，所以這次只是例行。","說話者認為兩人從來沒有見過。"]},"advanced-native-1670-v2-reply":{"type":"mc","answers":["We see each other once in a blue moon because we live far apart.","There are usually long gaps between our meetings.","It was a rare chance to spend time together.","The distance means we do not often get an afternoon like that."],"options":["We see each other once in a blue moon because we live far apart.","There are usually long gaps between our meetings.","It was a rare chance to spend time together.","The distance means we do not often get an afternoon like that."]},"advanced-native-1670-v1-scene":{"type":"mc","answers":["A theatre group comes here once in a blue moon."],"options":["A theatre group comes here once in a blue moon.","A theatre group performs here every week as part of a regular season.","The account gives an exact monthly interval for every visit."]},"advanced-native-1670-v1-contrast":{"type":"mc","answers":["事情從未發生，而且往後不可能發生。"],"options":["情境可交代為何這次機會值得珍惜。","事情發生得很罕有。","事情從未發生，而且往後不可能發生。"]},"advanced-native-1670-v1-branch":{"type":"mc","answers":["Once in a blue moon means rarely, not never; this afternoon was one of those rare meetings."],"options":["The rare afternoon should be counted as an ordinary weekly meeting.","The phrase supplies the exact number of months since the previous meeting.","Once in a blue moon means rarely, not never; this afternoon was one of those rare meetings."]},"advanced-native-1670-v1-final":{"type":"open","answers":["We use the noodle maker once in a blue moon, so you are welcome to borrow it for the demonstration. Could we agree a return date?","It comes out of the cupboard once in a blue moon, rather than every weekend. I am happy to lend it if we arrange when it will come back."],"options":[]}}'::jsonb),
('advanced-native-1671', '["phrase"]'::jsonb, '{"advanced-native-1671-v1-audio":{"type":"mc","answers":["小組後來失去推進動力，工作仍未完成。"],"options":["小組剛獲更多人手，開始安排更密集訪問。","停滯主要因所有受訪者已取消，並非組員不再推進。","小組後來失去推進動力，工作仍未完成。","所有故事已收齊，訊息只在宣布結束。"]},"advanced-native-1671-v2-reply":{"type":"mc","answers":["People stopped replying and no one proposed the next visit.","The initial enthusiasm did not carry through to the remaining work.","The project lost momentum even though stories were still waiting to be collected.","The group ran out of steam after the early burst of interviews."],"options":["People stopped replying and no one proposed the next visit.","The initial enthusiasm did not carry through to the remaining work.","The project lost momentum even though stories were still waiting to be collected.","The group ran out of steam after the early burst of interviews."]},"advanced-native-1671-v1-scene":{"type":"mc","answers":["She has run out of steam for the moment, though she still wants to finish."],"options":["The passage says she has decided never to write again.","She has run out of steam for the moment, though she still wants to finish.","She has completed the entire story and is only choosing where to publish it."]},"advanced-native-1671-v1-contrast":{"type":"mc","answers":["日後已不可能再繼續或找到新動力。"],"options":["需看上下文才知道是人累了、熱誠下降還是計劃停滯。","當時繼續的精力或推進動力下降。","日後已不可能再繼續或找到新動力。"]},"advanced-native-1671-v1-branch":{"type":"mc","answers":["We have run out of steam, so let us agree one manageable visit and ask who can help before promising a full season."],"options":["We have run out of steam, so let us agree one manageable visit and ask who can help before promising a full season.","Wait until the whole group feels as enthusiastic as it did at the start before discussing any next step.","Publish the full season now and find out afterwards whether anyone has time to organise it."]},"advanced-native-1671-v1-final":{"type":"open","answers":["I have run out of steam after walking all day, but I really enjoyed the market. Could we sit down for tea and talk about our favourite stalls?","I am running out of steam, not losing interest in the day we have shared. I would love a quiet cup of tea and a chance to hear which stall you liked best."],"options":[]}}'::jsonb),
('advanced-native-1672', '["phrase"]'::jsonb, '{"advanced-native-1672-v1-audio":{"type":"mc","answers":["小組想改善玩家決策的品質，而非只增加同類卡。"],"options":["原型已在比賽取得更高分數，句子在報告名次。","小組認為卡越多便越好，不需改玩家選擇。","原型從未能運作，小組決定完全棄掉遊戲。","小組想改善玩家決策的品質，而非只增加同類卡。"]},"advanced-native-1672-v2-reply":{"type":"mc","answers":["The aim was to improve the quality of the choices within a game that already worked.","We hoped to make the play more engaging without merely increasing the card count.","We wanted to level it up by making each turn involve a meaningful choice.","Players needed more interesting decisions, not just more copies of the same effect."],"options":["The aim was to improve the quality of the choices within a game that already worked.","We hoped to make the play more engaging without merely increasing the card count.","We wanted to level it up by making each turn involve a meaningful choice.","Players needed more interesting decisions, not just more copies of the same effect."]},"advanced-native-1672-v1-scene":{"type":"mc","answers":["The introduction is clear, and I want to level it up with a sharper comparison and smoother transitions."],"options":["The introduction needs a longer list of facts before the links between its ideas are considered.","The introduction is clear, and I want to level it up with a sharper comparison and smoother transitions.","The introduction needs only a higher page count, regardless of how the argument connects."]},"advanced-native-1672-v1-contrast":{"type":"mc","answers":["只把頁數或物件數加倍，不說品質有甚麼變化。"],"options":["指出原本限制，提出能改善體驗的改動。","只把頁數或物件數加倍，不說品質有甚麼變化。","說明由目前標準向哪個較高要求前進。"]},"advanced-native-1672-v1-branch":{"type":"mc","answers":["To level it up, we should ask what decision becomes more interesting, not just count the cards."],"options":["Add the same effects again before deciding what players find repetitive.","To level it up, we should ask what decision becomes more interesting, not just count the cards.","Use the bigger deck as the complete test of whether the game improved."]},"advanced-native-1672-v1-final":{"type":"open","answers":["Our recipe booklet is complete, but I want to level it up with an index of the main ingredients. Could you help us check whether readers can find a dish more easily?","The booklet has enough recipes; we could level it up by improving how people search for a dish. I would value your advice on a clear ingredient index."],"options":[]}}'::jsonb),
('advanced-native-1673', '["phrase"]'::jsonb, '{"advanced-native-1673-v1-audio":{"type":"mc","answers":["兩組給訪客的登記先後指引互相矛盾。"],"options":["兩組給訪客的登記先後指引互相矛盾。","兩組使用不同語氣，但給的是同樣登記步驟。","兩組已確認一套新流程，訪客只在問例外。","分別只在導賞路線長短，沒有涉及登記時間。"]},"advanced-native-1673-v2-reply":{"type":"mc","answers":["Visitors heard two different answers to the same practical question.","The teams were not singing from the same song sheet about when to register.","One team said to register before the tour, and the other said afterwards.","The instructions gave conflicting sequences for the same process."],"options":["Visitors heard two different answers to the same practical question.","The teams were not singing from the same song sheet about when to register.","One team said to register before the tour, and the other said afterwards.","The instructions gave conflicting sequences for the same process."]},"advanced-native-1673-v1-scene":{"type":"mc","answers":["They are singing from the same song sheet on the evidence, even though their examples differ."],"options":["Using different examples shows that they disagree about which facts were checked.","Agreement on the evidence requires them to repeat every sentence in the same style.","They are singing from the same song sheet on the evidence, even though their examples differ."]},"advanced-native-1673-v1-contrast":{"type":"mc","answers":["每個人的所有意見及表達風格都完全相同。"],"options":["仍需上下文指出正在協調哪項事情。","對相關做法或理解互相配合。","每個人的所有意見及表達風格都完全相同。"]},"advanced-native-1673-v1-branch":{"type":"mc","answers":["A friendly tone is not enough; we need to sing from the same song sheet on the registration sequence."],"options":["Use the shared friendly tone as confirmation that the instructions match.","Let each team keep its sequence and ask visitors to choose which one sounds nicer.","A friendly tone is not enough; we need to sing from the same song sheet on the registration sequence."]},"advanced-native-1673-v1-final":{"type":"open","answers":["Thank you for checking the revision and feedback arrangements with us; we are now singing from the same song sheet on those points. I appreciate having a common account for students while keeping our own examples.","We are singing from the same song sheet about the revision opportunity and the two areas of feedback after today’s meeting. Thank you for helping us align the framework without asking us to teach in identical styles."],"options":[]}}'::jsonb),
('advanced-native-1674', '["phrase"]'::jsonb, '{"advanced-native-1674-v1-audio":{"type":"mc","answers":["她想在忙完聚會後，翌晨暫時輕鬆一下。"],"options":["其他人正在等待她主持另一場同樣繁忙的聚會。","她想在忙完聚會後，翌晨暫時輕鬆一下。","她已決定從此不再參與任何家庭活動。","她仍在指揮每項早餐工作，沒有交給其他人。"]},"advanced-native-1674-v2-reply":{"type":"mc","answers":["She wanted to sit back and take it easy after hosting everyone.","She hoped for a relaxed morning without organising another full set of activities.","She was happy for the others to handle breakfast and their own plans.","She wanted a period with less effort, not a permanent end to family gatherings."],"options":["She wanted to sit back and take it easy after hosting everyone.","She hoped for a relaxed morning without organising another full set of activities.","She was happy for the others to handle breakfast and their own plans.","She wanted a period with less effort, not a permanent end to family gatherings."]},"advanced-native-1674-v1-scene":{"type":"mc","answers":["She wants to sit back and take it easy for the afternoon."],"options":["She plans another demanding walk instead of staying by the sea.","She wants to sit back and take it easy for the afternoon.","She has decided that she no longer wants to see the friends on the trip."]},"advanced-native-1674-v1-contrast":{"type":"mc","answers":["人物已永久放棄所有責任及興趣。"],"options":["需看上下文才知是短暫休息還是較長期生活選擇。","當時想放鬆，少作費力活動。","人物已永久放棄所有責任及興趣。"]},"advanced-native-1674-v1-branch":{"type":"mc","answers":["She wants to sit back and take it easy this afternoon; that does not cancel the dinner she agreed to."],"options":["Take the quiet afternoon as a cancellation of the dinner she has already accepted.","Fill her free afternoon with another guided tour before asking whether she wants it.","She wants to sit back and take it easy this afternoon; that does not cancel the dinner she agreed to."]},"advanced-native-1674-v1-final":{"type":"open","answers":["I would be happy to sit back and take it easy with you, sharing a simple lunch and a conversation. Please do not feel you need to plan a tour of every local sight.","We can sit back and take it easy this weekend rather than rush through a full programme. Spending time together matters more to me than the number of places we visit."],"options":[]}}'::jsonb),
('advanced-native-1676', '["phrase"]'::jsonb, '{"advanced-native-1676-v1-audio":{"type":"mc","answers":["老師重視可長久支撐學生的能力，不只短期考試。"],"options":["老師認為求助能力只適用於下次測驗。","學生已完成多年工作，老師在報告他們的結果。","老師主要按學生下次測驗的分數，判斷求助及聆聽的價值。","老師重視可長久支撐學生的能力，不只短期考試。"]},"advanced-native-1676-v2-reply":{"type":"mc","answers":["They could help pupils respond to many later situations.","Her aim was lasting support, not just a short-term examination result.","She hoped those skills would carry them well through life.","She saw value in them beyond the next test."],"options":["They could help pupils respond to many later situations.","Her aim was lasting support, not just a short-term examination result.","She hoped those skills would carry them well through life.","She saw value in them beyond the next test."]},"advanced-native-1676-v1-scene":{"type":"mc","answers":["He hopes those habits will carry him well through life."],"options":["He hopes those habits will carry him well through life.","He expects those habits to matter only until this apprenticeship ends.","He is describing results already measured throughout his whole career."]},"advanced-native-1676-v1-contrast":{"type":"mc","answers":["有了這特質，今後遇到的困難就不需要另求協助。"],"options":["需交代是甚麼特質支持哪些人。","某特質可在人生不同階段提供支撐。","有了這特質，今後遇到的困難就不需要另求協助。"]},"advanced-native-1676-v1-branch":{"type":"mc","answers":["She hopes the skills will carry them well through life, so her purpose reaches beyond this test."],"options":["We should treat the later-life comment as another name for the next test result.","Judge those skills only by the next test result, rather than consider how pupils might use them later.","She hopes the skills will carry them well through life, so her purpose reaches beyond this test."]},"advanced-native-1676-v1-final":{"type":"open","answers":["Your willingness to admit what you do not know and keep learning could carry you well through life. I hope you keep that openness when you meet new challenges.","The thoughtful way you learn can carry you well through life, far beyond this graduation. I value that quality as much as the work on display."],"options":[]}}'::jsonb),
('advanced-native-1677', '["phrase"]'::jsonb, '{"advanced-native-1677-v1-audio":{"type":"mc","answers":["她想改善較長時間持續步行的能力。"],"options":["她想改善較長時間持續步行的能力。","她主要想在起步幾秒走得比其他人快。","她已能輕鬆完成大隊所有較長路線。","她主要想認清路線及地標，而不是改善持續步行能力。"]},"advanced-native-1677-v2-reply":{"type":"mc","answers":["She wanted more endurance for the longer walk, rather than a faster start.","She wanted to build stamina so she could keep going for longer.","She hoped to sustain the effort beyond the opening stretch.","Her concern was getting tired before the usual turning point."],"options":["She wanted more endurance for the longer walk, rather than a faster start.","She wanted to build stamina so she could keep going for longer.","She hoped to sustain the effort beyond the opening stretch.","Her concern was getting tired before the usual turning point."]},"advanced-native-1677-v1-scene":{"type":"mc","answers":["She wants to build stamina for the longer passages."],"options":["The account says she has already completed a long performance without tiring.","She wants to build stamina for the longer passages.","Her main goal is to reach a higher note in one brief phrase."]},"advanced-native-1677-v1-contrast":{"type":"mc","answers":["只記錄一次起步加快，沒有持續能力的資料。"],"options":["目標關乎減少長時間活動中途疲累。","逐漸能較長時間維持一項活動。","只記錄一次起步加快，沒有持續能力的資料。"]},"advanced-native-1677-v1-branch":{"type":"mc","answers":["A quicker start does not show whether she has built stamina for the rest of the outing."],"options":["A quicker start does not show whether she has built stamina for the rest of the outing.","Use the faster opening seconds as the result for the whole outing.","Compare only her starting position with the others rather than how long she can continue."]},"advanced-native-1677-v1-final":{"type":"open","answers":["I would like to build stamina for longer reception shifts, but I have only done short ones so far. Could we discuss a shorter first shift and suitable breaks?","My aim is to build stamina for the exhibition work rather than promise a full day immediately. Please let me know whether we can agree a gradual start."],"options":[]}}'::jsonb),
