('advanced-native-1679', '["phrase"]'::jsonb, '{"advanced-native-1679-v1-audio":{"type":"mc","answers":["學生到實地比較資料，之後仍有課堂整理。"],"options":["參觀只在課室用照片進行，沒到實地。","學生未獲安排，私自離開來避過歷史課。","學生到實地比較資料，之後仍有課堂整理。","學生離開後已結束本周所有學習工作。"]},"advanced-native-1679-v2-reply":{"type":"mc","answers":["We saw the buildings that the old plan referred to.","The visit gave us direct observations to write about afterwards.","It connected the classroom material with a real place.","We could get out of the classroom and compare the plan with the actual street."],"options":["We saw the buildings that the old plan referred to.","The visit gave us direct observations to write about afterwards.","It connected the classroom material with a real place.","We could get out of the classroom and compare the plan with the actual street."]},"advanced-native-1679-v1-scene":{"type":"mc","answers":["The activity helps them get out of the classroom and make observations at the pond."],"options":["They finish their learning as soon as they leave the classroom door.","They make all their observations from pond pictures without leaving their seats.","The activity helps them get out of the classroom and make observations at the pond."]},"advanced-native-1679-v1-contrast":{"type":"mc","answers":["當事人一定在逃避課程或拒絕學習。"],"options":["需看情境才知道活動是否屬課程安排。","離開課室到別處活動。","當事人一定在逃避課程或拒絕學習。"]},"advanced-native-1679-v1-branch":{"type":"mc","answers":["We can get out of the classroom and still learn; comparing the plan with the street is part of the task."],"options":["We should replace the comparison task with free time because the lesson cannot continue outside.","We can get out of the classroom and still learn; comparing the plan with the street is part of the task.","Only the notes written before the visit can count as history learning."]},"advanced-native-1679-v1-final":{"type":"open","answers":["Thank you for helping us get out of the classroom and talk with residents about everyday expressions. We appreciated the conversation