('advanced-native-1680', '["phrase"]'::jsonb, '{"advanced-native-1680-v1-audio":{"type":"mc","answers":["排練時段被其他課擠壓，只剩短空檔。"],"options":["排練時段被其他課擠壓，只剩短空檔。","校劇已正式取消，所以不再有演出。","新增課主要擴充排練，演員有更多完整時段。","時間表維持原樣，演員只在選劇本。"]},"advanced-native-1680-v2-reply":{"type":"mc","answers":["The performance remained planned, but rehearsal time had become fragmented.","The play was squeezed to the edges of the timetable by the extra sessions.","They had only short gaps left for rehearsals.","Other scheduled demands had taken the longer shared periods."],"options":["The performance remained planned, but rehearsal time had become fragmented.","The play was squeezed to the edges of the timetable by the extra sessions.","They had only short gaps left for rehearsals.","Other scheduled demands had taken the longer shared periods."]},"advanced-native-1680-v1-scene":{"type":"mc","answers":["The exchange has been squeezed to the edges of the timetable."],"options":["The exchange now has a longer uninterrupted period than before.","The centre has removed the exchange from its programme altogether.","The exchange has been squeezed to the edges of the timetable."]},"advanced-native-1680-v1-contrast":{"type":"mc","answers":["某活動仍有完整固定時段，只把內容題目換新。"],"options":["活動未取消，但獲分配時間明顯受壓。","其他活動佔優先，某項只餘短零碎時段。","某活動仍有完整固定時段，只把內容題目換新。"]},"advanced-native-1680-v1-branch":{"type":"mc","answers":["It has not been cancelled, but it has been squeezed to the edges of the timetable and needs a usable rehearsal slot."],"options":["Spend the next meeting choosing costumes before checking whether the cast can share any rehearsal time.","It has not been cancelled, but it has been squeezed to the edges of the timetable and needs a usable rehearsal slot.","Keep treating the original rehearsal period as available because the performance is still listed."]},"advanced-native-1680-v1-final":{"type":"open","answers":["Last time, questions were squeezed to the edges of the timetable, so I appreciated the ten-minute discussion t