('advanced-native-1682', '["phrase"]'::jsonb, '{"advanced-native-1682-v1-audio":{"type":"mc","answers":["主要困難是多項功課同時到期帶來的負荷。"],"options":["導師已取消那三份作業，沒有工作剩下。","說話者只在回顧已交作業得到的分數。","主要困難是多項功課同時到期帶來的負荷。","說話者表示所有主題都完全不明白。"]},"advanced-native-1682-v2-reply":{"type":"mc","answers":["The amount of work was difficult to manage in the time available.","I understood the topics but needed help prioritising the tasks.","Several deadlines came together, leaving me unsure where to start.","I felt buried in homework with several assignments due together."],"options":["The amount of work was difficult to manage in the time available.","I understood the topics but needed help prioritising the tasks.","Several deadlines came together, leaving me unsure where to start.","I felt buried in homework with several assignments due together."]},"advanced-native-1682-v1-scene":{"type":"mc","answers":["She feels buried in homework despite her interest in the subjects."],"options":["She is describing a loss of interest rather than pressure from the workload.","The tasks have already been handed in and she is waiting only for marks.","She feels buried in homework despite her interest in the subjects."]},"advanced-native-1682-v1-contrast":{"type":"mc","answers":["人物一定對所有學科都沒有興趣。"],"options":["人物一定對所有學科都沒有興趣。","需看時間及任務，才知哪項支援有用。","功課量令人物感到難應付。"]},"advanced-native-1682-v1-branch":{"type":"mc","answers":["I am buried in homework because several tasks are due together, not because every question is unclear."],"options":["My main difficulty is understanding a new topic, rather than fitting the work into the week.","I am buried in homework because several tasks are due together, not because every question is unclear.","Explain each topic from the beginning before we look at when the assignments are due."]},"advanced-native-1682-v1-final":{"type":"open","answers":["I am buried in homework this week, but I would still like to see you. Could we meet for an hour on Saturday evening instead of spending the