('advanced-native-1684', '["phrase"]'::jsonb, '{"advanced-native-1684-v1-audio":{"type":"mc","answers":["說話者疲累地坐倒，想先休息再回訊息。"],"options":["說話者疲累地坐倒，想先休息再回訊息。","說話者已回完全部訊息，現在準備搬箱。","說話者先從容脫鞋、回好訊息，才慢慢選一個舒服姿勢坐下。","說話者剛休息完，立即開始下一段搬運。"]},"advanced-native-1684-v2-reply":{"type":"mc","answers":["The work had left me very tired, so I did not start replying immediately.","I collapsed onto the sofa after carrying the boxes and needed a quiet moment.","I felt worn out after the clearing and wanted to pause first.","I sat down heavily before I had even taken off my shoes."],"options":["The work had left me very tired, so I did not start replying immediately.","I collapsed onto the sofa after carrying the boxes and needed a quiet moment.","I felt worn out after the clearing and wanted to pause first.","I sat down heavily before I had even taken off my shoes."]},"advanced-native-1684-v1-scene":{"type":"mc","answers":["She collapsed onto the sofa and left the letters for a little later."],"options":["She collapsed onto the sofa and left the letters for a little later.","She finished opening all the letters before sitting down.","She carefully settled on the sofa after first arranging the letters for an immediate reading session."]},"advanced-native-1684-v1-contrast":{"type":"mc","answers":["人物必定失去知覺，需要敘述中未提的救治。"],"options":["人物很累地坐下或倒到沙發上。","人物必定失去知覺，需要敘述中未提的救治。","上下文可交代此前忙甚麼及之後想休息。"]},"advanced-native-1684-v1-branch":{"type":"mc","answers":["He collapsed onto the sofa because he felt worn out; sitting down does not tell us he is ready for another task."],"options":["Ask him to begin sorting the next boxes before finding out whether he needs that quiet moment.","He collapsed onto the sofa because he felt worn out; sitting down does not tell us he is ready for another task.","Use his sitting down as confirmation that he has already finished resting."]},"advanced-native-1684-v1-final":{"type":"open","answers":["Show him collapsing onto the sofa after the long day of guiding visitors,