('advanced-native-1686', '["phrase"]'::jsonb, '{"advanced-native-1686-v1-audio":{"type":"mc","answers":["新方式若無後備，群體預約機會差距可能加大。"],"options":["報告只擔心所有預約同樣變慢，不涉及群體使用機會不同。","報告認為只要有新系統，兩群體差距便一定縮小。","新方式若無後備，群體預約機會差距可能加大。","報告已量得每個群體的最新預約成功率。"]},"advanced-native-1686-v2-reply":{"type":"mc","answers":["The new method could leave some people further behind in getting a place.","Access to reservations might become less equal rather than more equal.","It warns of a larger difference in opportunity, not a measured new result.","The gap may actually grow wider if people without reliable access have no alternative."],"options":["The new method could leave some people further behind in getting a place.","Access to reservations might become less equal rather than more equal.","It warns of a larger difference in opportunity, not a measured new result.","The gap may actually grow wider if people without reliable access have no alternative."]},"advanced-native-1686-v1-scene":{"type":"mc","answers":["The gap may actually grow wider if the extra help reaches only those who already have more support."],"options":["The gap may actually grow wider if the extra help reaches only those who already have more support.","The latest results already show that every group improved by the same amount.","Offering an activity proves that the difference in access has already disappeared."]},"advanced-native-1686-v1-contrast":{"type":"mc","answers":["差距已按最新數據確認增大。"],"options":["差距已按最新數據確認增大。","需交代比較群體及條件，才明白這警告。","差距增大是值得留意的可能情況。"]},"advanced-native-1686-v1-branch":{"type":"mc","answers":["The gap may actually grow wider, but we need new evidence before stating how much it has changed."],"options":["Since the new figures are not available, leave the access risk out of the discussion.","The gap may actually grow wider, but we need new evidence before stating how much it has changed.","Use the warning itself as the size of the increase in the latest results."]},"advanced-native-1686-v1-final":{"type":"