('advanced-native-1687', '["phrase"]'::jsonb, '{"advanced-native-1687-v1-audio":{"type":"mc","answers":["他開始具體投入自己的日常目標，而非只收資訊。"],"options":["朋友替他決定所有生活選擇，沒有問他的目標。","他開始具體投入自己的日常目標，而非只收資訊。","他已得到所有習慣改善身體的實測結果。","他只在收集更多資訊，未想落實任何安排。"]},"advanced-native-1687-v2-reply":{"type":"mc","answers":["He began to lean into healthy habits by protecting a lunch break he had chosen.","He moved from collecting advice to making a specific arrangement.","He asked for practical support to keep time for his own routine.","His plan involved participation rather than simply storing suggestions."],"options":["He began to lean into healthy habits by protecting a lunch break he had chosen.","He moved from collecting advice to making a specific arrangement.","He asked for practical support to keep time for his own routine.","His plan involved participation rather than simply storing suggestions."]},"advanced-native-1687-v1-scene":{"type":"mc","answers":["She is beginning to lean into healthy habits rather than only save lists."],"options":["She is beginning to lean into healthy habits rather than only save lists.","Her saved lists are the only action described; no shared arrangement is being tried.","The story reports a measured health improvement caused by the new routine."]},"advanced-native-1687-v1-contrast":{"type":"mc","answers":["單憑這用語已知個人的健康指標改善。"],"options":["更主動參與相關日常安排。","單憑這用語已知個人的健康指標改善。","情境應交代習慣及投入方式，不只用抽象標語。"]},"advanced-native-1687-v1-branch":{"type":"mc","answers":["I said he was starting to lean into healthy habits, not that the story had proved a health result."],"options":["I said he was starting to lean into healthy habits, not that the story had proved a health result.","Count the new plan itself as the measured improvement, without waiting for any observation.","Because no result is reported, leave out the concrete effort he has already made."]},"advanced-native-1687-v1-final":{"type":"open","answers":["Thank you for joining the walks we chose; I want to lean into hea